import sqlparse

tests = [
    'WHERE',
    'foo where',
    'SELECT * FROM foo WHERE',
    'foo WHERE bar = 1 and',
    'SELECT * FROM foo WHERE bar = %s AND',
]
for sql in tests:
    try:
        print(sql, '->', repr(sqlparse.format(sql, reindent=True)))
    except Exception as e:
        print(sql, '-> ERROR', type(e).__name__, e)

